/* Тело «Начало списка»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_nachalo_spiska_body(fl_ctx *ctx, fl_value simvoly, fl_value skolko, fl_value *result, fl_error *error) {
  fl_value fl_t108 = fl_nothing();
  FL_TRY(fl_lte(ctx, skolko, fl_number(0.0), &fl_t108, error));
  bool fl_t109 = false;
  FL_TRY(fl_cond(ctx, fl_t108, &fl_t109, error));
  if (fl_t109) {
    *result = kompilyator_flang_text_157;
    return FL_OK;
  } else {
    if (fl_chain_empty(simvoly)) {
      *result = kompilyator_flang_text_157;
      return FL_OK;
    } else if (fl_chain_cons(simvoly)) {
      const fl_value golova = fl_chain_head(simvoly); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(simvoly); /* хвост «хвост» */
      fl_value fl_t110 = fl_nothing();
      FL_TRY(fl_sub(ctx, skolko, fl_number(1.0), &fl_t110, error));
      fl_value fl_t111 = fl_nothing();
      FL_TRY(kompilyator_flang_nachalo_spiska(ctx, hvost, fl_t110, &fl_t111, error));
      fl_value fl_t112 = fl_nothing();
      FL_TRY(fl_concat(ctx, golova, fl_t111, &fl_t112, error));
      *result = fl_t112;
      return FL_OK;
    } else {
      return fl_match_fail(ctx, simvoly, error);
    }
  }
}

