/* Шаг батута для «Связать поля варианта»: значение либо отскок к соседу по рекурсии. */
static fl_status kompilyator_flang_svyazat_polya_varianta_step(fl_ctx *ctx, const fl_value *args, fl_bounce *bounce, fl_value *result,
                                                               fl_error *error) {
  fl_value svyazki = args[0]; /* «связки» */
  fl_value obyavleno = args[1]; /* «объявлено» */
  fl_value imya_varianta = args[2]; /* «имя варианта» */
  fl_value imena = args[3]; /* «имена» */
  fl_value podstanovka = args[4]; /* «подстановка» */
  fl_value mesto = args[5]; /* «место» */
  fl_value bedy = args[6]; /* «беды» */
  if (fl_chain_empty(svyazki)) {
    fl_value fl_t13597[2];
    fl_t13597[0] = imena; /* «имена» */
    fl_t13597[1] = bedy; /* «беды» */
    fl_value fl_t13596 = fl_nothing();
    FL_TRY(fl_record_new(ctx, kompilyator_flang_names_100, fl_t13597, 2, &fl_t13596, error));
    *result = fl_t13596;
    return FL_OK;
  } else if (fl_chain_cons(svyazki)) {
    const fl_value golova = fl_chain_head(svyazki); /* голова «голова» */
    const fl_value hvost = fl_chain_tail(svyazki); /* хвост «хвост» */
    /* хвостовой вызов «Связать поле варианта» — отскок, а не кадр стека */
    bounce->args[0] = golova;
    bounce->args[1] = hvost;
    bounce->args[2] = obyavleno;
    bounce->args[3] = imya_varianta;
    bounce->args[4] = imena;
    bounce->args[5] = podstanovka;
    bounce->args[6] = mesto;
    bounce->args[7] = bedy;
    bounce->next = kompilyator_flang_svyazat_pole_varianta_step;
    return FL_OK;
  } else {
    return fl_match_fail(ctx, svyazki, error);
  }
}

